var n=`0392-quetschentaart`;var r=`world-0392`;var s=`LU`;var a=`western-europe`;var i=4;var o=62;var u={en:`Quetschentaart`,ua:`Сливовий тарт`};var d={en:`A traditional Luxembourg dish made with shortcrust pastry, plum. This home-style preparation follows its characteristic cooking method and uses measured ingredients.`,ua:`Традиційна страва кухні країни Люксембург. Основні інгредієнти: пісочне тісто, слива. Домашній варіант із характерною технологією та поетапно розподіленими продуктами.`};var g=[{en:`Roll or press the prepared dough evenly into the desired thickness and shape.`,ua:`Розкачайте або розпластайте підготовлене тісто рівномірним шаром потрібної товщини та форми.`,t:[`pressing`,`rolling-out-dough`],m:12,i:[[`shortcrust-pastry`,450,`g`]]},{en:`Layer the prepared elements evenly in the baking dish, spreading filling right to the edges.`,ua:`Викладіть підготовлені компоненти рівними шарами у формі, розподіляючи начинку до країв.`,t:[`layered-assembly`],m:8,i:[[`plum`,900,`g`],[`white-granulated-sugar`,125,`g`],[`ground-cinnamon`,4,`g`]]},{en:`Bake in a preheated 180°C oven for about 42 minutes until set, golden and cooked through. Cool on a rack.`,ua:`Випікайте в розігрітій до 180°C духовці приблизно 42 хвилин до рум’яності та повної готовності. Остудіть на решітці.`,t:[`baking`],m:42,i:[]}];var h={slug:n,id:r,country:`LU`,region:a,servings:4,minutes:62,title:u,text:d,steps:g};export{s as country,h as default,r as id,o as minutes,a as region,i as servings,n as slug,g as steps,d as text,u as title};